pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 burnAmount, bool callOwned) public {
        vm.assume(c.totalSupply() >= burnAmount);
        address ownerBefore = c.owner();
        vm.prank(ownerBefore);
        try c.burn(burnAmount) { } catch { }
        if (callOwned) {
            vm.prank(address(this));
            try c.owned() { } catch { }
        }
        assertTrue(c.owner() != address(0));
    }
}
